import yt_dlp

VIDS = {
 'A': 'ixkoVwKQaJg',  # Taki Taki
 'B': 'DiItGE3eAyQ',  # Con Calma
 'C': 'kJQP7kiw5Fk',  # Despacito
 'D': 'VqEbCxg2bNI',  # Criminal
 'E': 'zEf423kYfqk',  # Sin Pijama
 'F': '_P7S2lKif-A',  # Bum Bum Tam Tam
 'G': 'TapXs54Ah3E',  # Ay Vamos
 'H': 'GMFewiplIbw',  # Mayores
 'I': '1_zgKRBrT0Y',  # Calma Remix
 'J': '6Mgqbai3fKo',  # Chantaje
}

def fetch(url):
    req = urllib.request.Request(url, headers={'User-Agent': 'Mozilla/5.0'})
    return urllib.request.urlopen(req, timeout=30).read()

results = {}
with yt_dlp.YoutubeDL({'quiet': True, 'skip_download': True, 'no_warnings': True,
                       'extractor_args': {'youtube': {'player_client': ['web']}}}) as ydl:
    for key, vid in VIDS.items():
        try:
            info = ydl.extract_info(f'https://www.youtube.com/watch?v={vid}', download=False)
            duration = info.get('duration')
            title = info.get('title')
            sb_fmts = [f for f in info.get('formats', []) if str(f.get('format_id', '')).startswith('sb')]
            sb_fmts.sort(key=lambda f: (f.get('width') or 0) * (f.get('height') or 0), reverse=True)
            if not sb_fmts:
                print(key, vid, 'NO STORYBOARD, dur', duration); continue
            fmt = sb_fmts[0]
            url = fmt['url']
            fw, fh = fmt.get('width'), fmt.get('height')
            sheets = []
            if '$M' in url:
                n = 0
                while n < 40:
                    try:
                        b = fetch(url.replace('$M', str(n)))
                    except Exception:
                        break
                    sheets.append(b); n += 1
            else:
                sheets.append(fetch(url))
            frames = []
            for b in sheets:
                im = Image.open(io.BytesIO(b)).convert('RGB')
                W, H = im.size
                cols, rows = max(1, W // fw), max(1, H // fh)
                for r in range(rows):
                    for c in range(cols):
                        tile = im.crop((c*fw, r*fh, (c+1)*fw, (r+1)*fh)).resize((1, 1), Image.BOX)
                        frames.append(tile.getpixel((0, 0)))
            results[key] = {'id': vid, 'title': title, 'duration': duration,
                            'fw': fw, 'fh': fh, 'fmt': fmt['format_id'], 'frames': frames}
            print(f"{key} {vid} '{title[:45]}' dur={duration}s fmt={fmt['format_id']} {fw}x{fh} sheets={len(sheets)} frames={len(frames)}")
        except Exception as e:
            print(key, vid, 'ERROR', repr(e))

json.dump(results, open('storyboards.json', 'w'))
print('saved', len(results), 'entries')
