    url = f'https://www.youtube.com/watch?v={vid}&bpctr=9999999999&has_verified=1'
    req = urllib.request.Request(url, headers=UA)
    return urllib.request.urlopen(req, timeout=30).read().decode('utf-8', 'ignore')

def player_response(html):
    m = re.search(r'ytInitialPlayerResponse\s*=\s*', html)
    i = m.end(); depth = 0; instr = False; esc = False; start = i
    for j in range(i, min(i + 2_000_000, len(html))):
        ch = html[j]
        if instr:
            if esc: esc = False
            elif ch == '\\': esc = True
            elif ch == '"': instr = False
        else:
            if ch == '"': instr = True
            elif ch == '{': depth += 1
            elif ch == '}':
                depth -= 1
                if depth == 0:
                    return json.loads(html[start:j+1])

def fetch(url):
    req = urllib.request.Request(url, headers=UA)
    return urllib.request.urlopen(req, timeout=30).read()

out = {}
for key, vid in VIDS.items():
    try:
        pr = player_response(get_page(vid))
        vd = pr.get('videoDetails', {})
        title = vd.get('title'); dur = int(vd.get('lengthSeconds', 0))
        spec = pr['storyboards']['playerStoryboardSpecRenderer']['spec']
        parts = spec.split('|')
        base = parts[0]
        levels = parts[1:][::-1]          # yt-dlp order: highest-res first
        L = len(levels) - 1
        best = None
        for i, args in enumerate(levels):
            a = args.split('#')
            w, h, fc, cols, rows = map(int, a[:5])
            N, sigh = a[6], a[7]
            url = base.replace('$L', str(L - i)).replace('$N', N) + f'&sigh={sigh}'
            if best is None or w * h > best['w'] * best['h']:
                best = dict(w=w, h=h, fc=fc, cols=cols, rows=rows, url=url, lvl=str(L - i))
        n_sheets = math.ceil(best['fc'] / (best['cols'] * best['rows']))
        frames = []
        for k in range(n_sheets):
            b = fetch(best['url'].replace('$M', str(k)))
            im = Image.open(io.BytesIO(b)).convert('RGB')
            for r in range(best['rows']):
                for c in range(best['cols']):
                    if len(frames) >= best['fc']:
                        break
                    tile = im.crop((c*best['w'], r*best['h'], (c+1)*best['w'], (r+1)*best['h'])).resize((1,1), Image.BOX)
                    frames.append(tile.getpixel((0, 0)))
        times = [j * dur / best['fc'] for j in range(len(frames))]
        out[key] = {'id': vid, 'title': title, 'duration': dur, 'urllevel': best['lvl'],
                    'w': best['w'], 'h': best['h'], 'fc': best['fc'], 'interval_ms': None,
                    'frames': frames, 'times': times}
        print(f"{key} {vid} '{title[:40]}' dur={dur}s L{best['lvl']} {best['w']}x{best['h']} frames={len(frames)}/{best['fc']} sheets={n_sheets}")
    except Exception as e:
        print(key, vid, 'ERROR', repr(e))

json.dump(out, open('storyboards.json', 'w'))
print('saved', len(out))
